/* Version and immutable shell URLs are generated by scripts/build.mjs. */
const CACHE_PREFIX = 'liquid-synthetics-gallery-';
const CACHE_NAME = CACHE_PREFIX + '__CACHE_VERSION__';
const PRECACHE = __PRECACHE__;
const urls = PRECACHE.map(path => new URL(path, self.registration.scope).href);
const allowed = new Set(urls);
const indexURL = new URL(PRECACHE[0], self.registration.scope).href;
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(urls.map(url => new Request(url, { cache: 'reload' })));
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  const scope = new URL(self.registration.scope);
  // Release metadata, APKs, cross-origin requests and unknown URLs never enter our cache.
  if (request.method !== 'GET' || url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)
      || url.pathname.endsWith('.apk') || url.pathname === new URL('data/apps.json', scope).pathname) return;
  if (request.mode === 'navigate') {
    // Keep each document and its versioned assets together until an update is accepted.
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      return (await cache.match(indexURL)) || fetch(request);
    })());
  } else if (allowed.has(url.href)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      return (await cache.match(request)) || fetch(request);
    })());
  }
});
